alter table public.purchase_order_documents add column if not exists analysis_status text not null default 'pending' check(analysis_status in ('pending','processing','complete','failed','reviewed'));alter table public.purchase_order_documents add column if not exists analysis_json jsonb;alter table public.purchase_order_documents add column if not exists analyzed_at timestamptz;
create table if not exists public.vendor_bill_drafts(id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references public.purchase_orders(id) on delete cascade,document_id uuid not null unique references public.purchase_order_documents(id) on delete cascade,supplier_id uuid references public.suppliers(id) on delete set null,customer_id uuid references public.customers(id) on delete set null,invoice_number text,invoice_date date,due_date date,subtotal numeric not null default 0,tax numeric not null default 0,total numeric not null default 0,account_code text default 'materials_cogs',memo text,status text not null default 'needs_review' check(status in ('needs_review','approved','posted','rejected')),confidence numeric,extracted_json jsonb,approved_by uuid references public.users(id),approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index if not exists vendor_bill_drafts_status_idx on public.vendor_bill_drafts(status,created_at desc);alter table public.vendor_bill_drafts enable row level security;create policy "finance read vendor bill drafts" on public.vendor_bill_drafts for select to authenticated using(private.current_employee_role() in ('owner','manager','accounting'));create policy "finance manage vendor bill drafts" on public.vendor_bill_drafts for all to authenticated using(private.current_employee_role() in ('owner','manager','accounting')) with check(private.current_employee_role() in ('owner','manager','accounting'));
create or replace function public.approve_vendor_bill_draft(p_bill_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_user public.users%rowtype;v_bill public.vendor_bill_drafts%rowtype;begin select * into v_user from public.users where auth_user_id=auth.uid() and active=true limit 1;if v_user.id is null or v_user.role not in ('owner','manager','accounting') then raise exception 'not authorized';end if;select * into v_bill from public.vendor_bill_drafts where id=p_bill_id for update;if v_bill.id is null then raise exception 'bill not found';end if;if v_bill.total<=0 then raise exception 'bill total must be reviewed before approval';end if;update public.vendor_bill_drafts set status='approved',approved_by=v_user.id,approved_at=now(),updated_at=now() where id=p_bill_id;update public.purchase_order_documents set analysis_status='reviewed' where id=v_bill.document_id;insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(v_user.id,'approve_vendor_bill','vendor_bill',p_bill_id,jsonb_build_object('total',v_bill.total,'invoice_number',v_bill.invoice_number));return p_bill_id;end$$;revoke all on function public.approve_vendor_bill_draft(uuid) from public,anon;grant execute on function public.approve_vendor_bill_draft(uuid) to authenticated;
